interface MockResponse {
  status?: number;
  body?: unknown;
  headers?: Record<string, string>;
}

interface Recorded {
  method: string;
  url: URL;
  authorization: string | null;
  contentType: string | null;
  body: unknown;
}

/**
 * Serve `handler` on a local port and send every DNSimple base URL to it. The
 * handler receives the 1-based count of requests so far.
 */
async function withMockApi(
  handler: (req: Recorded, count: number) => MockResponse,
  fn: (requests: Recorded[]) => Promise<void>,
): Promise<void> {
  const requests: Recorded[] = [];
  const server = Deno.serve({ port: 0, onListen() {} }, async (req) => {
    const text = await req.text();
    const recorded: Recorded = {
      method: req.method,
      url: new URL(req.url),
      authorization: req.headers.get("authorization"),
      contentType: req.headers.get("content-type"),
      body: text ? JSON.parse(text) : undefined,
    };
    requests.push(recorded);
    const res = handler(recorded, requests.length);
    const status = res.status ?? 200;
    if (status === 204 || res.body === undefined) {
      return new Response(null, { status, headers: res.headers });
    }
    return Response.json(res.body, { status, headers: res.headers });
  });
  const addr = server.addr as Deno.NetAddr;
  const mockUrl = `http://localhost:${addr.port}`;
  const originalFetch = globalThis.fetch;
  globalThis.fetch = (input, init) => {
    const reqUrl = typeof input === "string" ? input : input.toString();
    return originalFetch(
      reqUrl
        .replace("https://api.dnsimple.com/v2", mockUrl)
        .replace("https://api.sandbox.dnsimple.com/v2", `${mockUrl}/sandbox`),
      init,
    );
  };
  try {
    await fn(requests);
  } finally {
    globalThis.fetch = originalFetch;
    await server.shutdown();
  }
}

const ARGS = { apiToken: "test-token", accountId: "1010" };

/** Run `fn` with the token env var set or removed, restoring it after. */
async function withTokenEnv(
  value: string | undefined,
  fn: () => Promise<void>,
): Promise<void> {
  const original = Deno.env.get("DNSIMPLE_TOKEN");
  try {
    if (value === undefined) Deno.env.delete("DNSIMPLE_TOKEN");
    else Deno.env.set("DNSIMPLE_TOKEN", value);
    await fn();
  } finally {
    if (original === undefined) Deno.env.delete("DNSIMPLE_TOKEN");
    else Deno.env.set("DNSIMPLE_TOKEN", original);
  }
}

