/** Run `fn` with `fetch` replaced by `stub`, restoring it after. */
async function withStubbedFetch(
  stub: typeof fetch,
  fn: () => Promise<void>,
): Promise<void> {
  const originalFetch = globalThis.fetch;
  globalThis.fetch = stub;
  try {
    await fn();
  } finally {
    globalThis.fetch = originalFetch;
  }
}

