Deno.test({
  name:
    "dnsimpleApiList: one request; truncated only when the response reports more pages",
  sanitizeResources: false,
  fn: async () => {
    await withMockApi(
      (req) => {
        switch (req.url.pathname) {
          case "/plain":
            return { body: { data: [{ id: 1 }] } };
          case "/last":
            return { body: page(2, 2, 1) };
          case "/more":
            return { body: page(1, 3, 1) };
          case "/odd":
            return {
              body: {
                data: [],
                pagination: { current_page: "x", total_pages: 2 },
              },
            };
          case "/null":
            return { body: { data: null } };
          default:
            return { status: 204 };
        }
      },
      async () => {
        assertEquals(await dnsimpleApiList(ARGS, "GET", "/plain"), {
          items: [{ id: 1 }],
          truncated: false,
        });
        assertEquals(
          (await dnsimpleApiList(ARGS, "GET", "/last")).truncated,
          false,
        );
        assertEquals(
          (await dnsimpleApiList(ARGS, "GET", "/more")).truncated,
          true,
        );
        // An unreadable current page counts as the first, never as complete.
        assertEquals(
          (await dnsimpleApiList(ARGS, "GET", "/odd")).truncated,
          true,
        );
        await assertRejects(
          () => dnsimpleApiList(ARGS, "GET", "/null"),
          Error,
          "null data",
        );
        await assertRejects(
          () => dnsimpleApiList(ARGS, "GET", "/gone"),
          Error,
          "empty response body",
        );
      },
    );
  },
});

/** A page body: `count` rows, claiming `pages` pages in all. */
function page(n: number, pages: number, count = 2) {
  return {
    data: Array.from({ length: count }, (_, i) => ({ id: n * 100 + i })),
    pagination: {
      current_page: n,
      per_page: 100,
      total_entries: pages * count,
      total_pages: pages,
    },
  };
}

Deno.test({
  name: "dnsimpleApiPaginated: walks every page and merges the results",
  sanitizeResources: false,
  fn: async () => {
    await withMockApi(
      (req) => ({ body: page(Number(req.url.searchParams.get("page")), 3) }),
      async (requests) => {
        const out = await dnsimpleApiPaginated<{ id: number }>(
          ARGS,
          "/1010/zones",
          { query: { name_like: "ex" } },
        );
        assertEquals(out.results.length, 6);
        assertEquals(out.truncated, false);
        assertEquals(out.totalEntries, 6);
        assertEquals(
          requests.map((r) => r.url.searchParams.get("page")),
          ["1", "2", "3"],
        );
        assertEquals(
          requests.every((r) =>
            r.url.searchParams.get("per_page") === "100" &&
            r.url.searchParams.get("name_like") === "ex"
          ),
          true,
        );
      },
    );
  },
});

Deno.test({
  name: "dnsimpleApiPaginated: a single page makes one request",
  sanitizeResources: false,
  fn: async () => {
    await withMockApi(() => ({ body: page(1, 1) }), async (requests) => {
      const out = await dnsimpleApiPaginated(ARGS, "/1010/zones");
      assertEquals(out.results.length, 2);
      assertEquals(requests.length, 1);
    });
  },
});

Deno.test({
  name: "dnsimpleApiPaginated: stops at MAX_PAGES and reports truncation",
  sanitizeResources: false,
  fn: async () => {
    await withMockApi(
      (req) => ({
        body: page(Number(req.url.searchParams.get("page")), MAX_PAGES + 10),
      }),
      async (requests) => {
        const out = await dnsimpleApiPaginated(ARGS, "/1010/zones");
        assertEquals(requests.length, MAX_PAGES);
        assertEquals(out.results.length, MAX_PAGES * 2);
        assertEquals(out.truncated, true);
        assertEquals(out.totalEntries, (MAX_PAGES + 10) * 2);
      },
    );
  },
});

Deno.test({
  name:
    "dnsimpleApiPaginated: a result set of exactly MAX_PAGES is not truncated",
  sanitizeResources: false,
  fn: async () => {
    await withMockApi(
      (req) => ({
        body: page(Number(req.url.searchParams.get("page")), MAX_PAGES),
      }),
      async (requests) => {
        const out = await dnsimpleApiPaginated(ARGS, "/1010/zones");
        assertEquals(requests.length, MAX_PAGES);
        assertEquals(out.truncated, false);
      },
    );
  },
});

Deno.test({
  name:
    "dnsimpleApiPaginated: reads results from a nested path and keeps siblings",
  sanitizeResources: false,
  fn: async () => {
    await withMockApi(
      (req) => {
        const n = Number(req.url.searchParams.get("page"));
        return {
          body: {
            data: {
              headers: n === 1 ? ["zone_name", "volume"] : ["ignored"],
              rows: [[`zone-${n}`, n]],
            },
            pagination: {
              current_page: n,
              per_page: 100,
              total_entries: 2,
              total_pages: 2,
            },
          },
        };
      },
      async () => {
        const out = await dnsimpleApiPaginated<unknown[]>(
          ARGS,
          "/1010/dns_analytics",
          { resultsPath: ["data", "rows"], keep: ["headers"] },
        );
        assertEquals(out.results, [["zone-1", 1], ["zone-2", 2]]);
        assertEquals(out.kept, { headers: ["zone_name", "volume"] });
      },
    );
  },
});

